  def bridged_share_url_button(description = nil)
    tag.button hidden: true, data: {
      controller: "bridge--share",
      action: "bridge--share#shareUrl",
      bridge__overflow_menu_target: "item",
      bridge_title: "Share"
    } do
      safe_join [ "Share", (tag.span(description, hidden: true, data: { bridge__share_target: "description" }) if description) ]
    end
  end

  def bridge_share_card_description(card)
    date_added = local_datetime_tag(card.created_at, style: :shortdate)
    date_updated = local_datetime_tag(card.last_active_at, style: :shortdate)
    author = card.creator.familiar_name
    assignees = card.assignees.any? ? "assigned to #{card.assignees.map(&:familiar_name).to_sentence}" : "not assigned"
    safe_join [ "Added ", date_added, " by #{author} and #{assignees}. Updated ", date_updated ]
  end
