import { BridgeComponent } from "@hotwired/hotwire-native-bridge"

export default class extends BridgeComponent {
  static component = "share"
  static targets = [ "description" ]

  shareUrl() {
    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: this.#description
    })
  }

  // Read from the page so dates rendered by the local-time controller are in the viewer's timezone
  get #description() {
    return this.hasDescriptionTarget ? this.descriptionTarget.textContent.trim().replace(/\s+/g, " ") : null
  }
}
